<?php

namespace App\Services;

use App\Models\Template;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;

/** Built-in certificate recipes; no prepackaged artwork or external font binaries. */
final class StarterTemplateService
{
    public static function catalog(): array
    {
        // Once the actual user's templates have been bundled, show those instead
        // of generic designs generated by Certify.
        $uploaded = BundledTemplateService::catalog();
        if ($uploaded !== []) return $uploaded;
        return [
            'academic' => ['name' => 'Academic Excellence', 'description' => 'Classic navy-and-gold academic award', 'orientation' => 'Landscape', 'tone' => 'classic'],
            'recognition' => ['name' => 'Modern Recognition', 'description' => 'Clean contemporary certificate', 'orientation' => 'Landscape', 'tone' => 'modern'],
            'appreciation' => ['name' => 'Formal Appreciation', 'description' => 'Formal portrait presentation', 'orientation' => 'Portrait', 'tone' => 'formal'],
            'participation' => ['name' => 'Participation Award', 'description' => 'Friendly participation certificate', 'orientation' => 'Landscape', 'tone' => 'friendly'],
        ];
    }

    public function create(string $id): Template
    {
        if (isset(BundledTemplateService::catalog()[$id])) {
            return app(BundledTemplateService::class)->create($id);
        }
        $catalog = self::catalog();
        if (! isset($catalog[$id])) {
            throw ValidationException::withMessages(['starter' => 'Unknown built-in certificate design.']);
        }
        if (! class_exists(\TCPDF::class)) {
            throw ValidationException::withMessages(['starter' => 'Install the TCPDF Composer dependency before using built-in designs.']);
        }
        $portrait = $id === 'appreciation';
        $width = $portrait ? 210 : 297;
        $height = $portrait ? 297 : 210;
        $pdf = new \TCPDF($portrait ? 'P' : 'L', 'mm', 'A4', true, 'UTF-8', false);
        $pdf->SetCreator('Certify');
        $pdf->SetAuthor('Certify');
        $pdf->SetTitle($catalog[$id]['name']);
        $pdf->setPrintHeader(false);
        $pdf->setPrintFooter(false);
        $pdf->SetMargins(0, 0, 0);
        $pdf->SetAutoPageBreak(false);
        $pdf->AddPage();
        $this->paint($pdf, $id, $width, $height);
        $bytes = $pdf->Output('', 'S');
        if (! is_string($bytes) || ! str_starts_with($bytes, '%PDF-')) {
            throw new \RuntimeException('Unable to generate the built-in certificate design.');
        }
        $disk = Storage::disk('local');
        $path = 'private/templates/'.Str::uuid().'.pdf';
        if (! $disk->put($path, $bytes)) {
            throw new \RuntimeException('Unable to save the starter template.');
        }
        try {
            return DB::transaction(function () use ($catalog, $id, $path, $width, $height) {
                $template = Template::create([
                    'name' => $catalog[$id]['name'], 'file_path' => $path,
                    'mime_type' => 'application/pdf', 'width_mm' => $width, 'height_mm' => $height,
                ]);
                $template->elements()->create([
                    'field_key' => 'recipient_name', 'kind' => 'text',
                    'x_mm' => 20, 'y_mm' => $height * 0.45,
                    'width_mm' => $width - 40, 'height_mm' => 22,
                    'z_index' => 0,
                    'settings' => ['font_family' => 'times', 'font_size' => 30, 'align' => 'C', 'bold' => true, 'color' => '#24344F', 'auto_fit' => true],
                ]);
                return $template;
            });
        } catch (\Throwable $error) {
            $disk->delete($path);
            throw $error;
        }
    }

    private function paint(\TCPDF $pdf, string $id, float $w, float $h): void
    {
        $navy = [30, 45, 70];
        $gold = [177, 135, 71];
        if ($id === 'academic') {
            $pdf->SetDrawColor(...$navy); $pdf->SetLineWidth(1.5); $pdf->Rect(9, 9, $w - 18, $h - 18);
            $pdf->SetDrawColor(...$gold); $pdf->SetLineWidth(0.55); $pdf->Rect(13, 13, $w - 26, $h - 26);
            $pdf->SetTextColor(...$navy);
            $this->center($pdf, 'CERTIFICATE OF EXCELLENCE', 31, 29, $w);
            $pdf->SetDrawColor(...$gold); $pdf->Line($w * .29, 67, $w * .71, 67);
            $this->center($pdf, 'PROUDLY PRESENTED TO', 13, 78, $w);
            $this->center($pdf, 'In recognition of distinguished achievement', 12, 141, $w);
            $this->center($pdf, 'AWARDED WITH APPRECIATION', 10, 170, $w);
        } elseif ($id === 'recognition') {
            $pdf->SetFillColor(38, 65, 82); $pdf->Rect(0, 0, 17, $h, 'F');
            $pdf->SetFillColor(229, 239, 238); $pdf->Rect(17, 0, 7, $h, 'F');
            $pdf->SetFillColor(233, 244, 240); $pdf->Rect($w-22, 0, 22, 38, 'F');
            $pdf->SetTextColor(30, 61, 67);
            $this->center($pdf, 'CERTIFICATE', 37, 33, $w);
            $this->center($pdf, 'OF RECOGNITION', 19, 52, $w);
            $this->center($pdf, 'THIS CERTIFICATE IS AWARDED TO', 12, 80, $w);
            $this->center($pdf, 'For outstanding commitment and contribution', 12, 145, $w);
            $pdf->SetDrawColor(46, 110, 109); $pdf->Line(63, 174, 234, 174);
        } elseif ($id === 'appreciation') {
            $pdf->SetFillColor(248, 247, 242); $pdf->Rect(0, 0, $w, $h, 'F');
            $pdf->SetDrawColor(...$gold); $pdf->SetLineWidth(1.1); $pdf->Rect(9, 9, $w - 18, $h - 18);
            $pdf->SetLineWidth(.35); $pdf->Rect(14, 14, $w - 28, $h - 28);
            $pdf->SetTextColor(...$navy);
            $this->center($pdf, 'CERTIFICATE', 31, 58, $w);
            $this->center($pdf, 'OF APPRECIATION', 17, 82, $w);
            $this->center($pdf, 'GRATEFULLY PRESENTED TO', 11, 111, $w);
            $this->center($pdf, 'For your valuable service and dedication', 12, 184, $w);
            $this->center($pdf, 'WITH SINCERE APPRECIATION', 10, 241, $w);
        } else {
            $pdf->SetFillColor(239, 246, 249); $pdf->Rect(0, 0, $w, $h, 'F');
            $pdf->SetFillColor(51, 123, 146); $pdf->Rect(0, 0, $w, 14, 'F');
            $pdf->SetFillColor(237, 177, 104); $pdf->Rect(0, $h-12, $w, 12, 'F');
            $pdf->SetTextColor(37, 74, 101);
            $this->center($pdf, 'CERTIFICATE OF PARTICIPATION', 26, 38, $w);
            $this->center($pdf, 'AWARDED TO', 13, 83, $w);
            $this->center($pdf, 'For active participation and meaningful engagement', 12, 146, $w);
            $this->center($pdf, 'THANK YOU FOR BEING PART OF IT', 10, 178, $w);
        }
    }

    private function center(\TCPDF $pdf, string $text, float $fontSize, float $y, float $width): void
    {
        $pdf->SetFont('helvetica', '', $fontSize);
        $pdf->SetXY(0, $y);
        $pdf->Cell($width, 16, $text, 0, 0, 'C', false, '', 0, false, 'T', 'M');
    }
}
